content.text:
{
  "primary_meaning": "The Messianic kingdom of God (Christ and/or His kingdom) of supernatural/divine origin that destroys all human kingdoms and fills the whole earth",
  "primary_basis": [
    "Daniel 2:34-35",
    "Daniel 2:44-45"
  ],
  "alternatives": [
    {
      "meaning": "Jesus Christ personally (the divine 'stone' or cornerstone of non-human origin, often linked to virgin birth or eternal Sonship)",
      "basis": [
        "Daniel 2:34-35,44-45",
        "Psalm 118:22",
        "Isaiah 28:16",
        "Matthew 21:42-44",
        "Acts 4:11",
        "1 Peter 2:4-8"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The Christian Church (as the mountain that grows from the stone and fills the earth)",
      "basis": [
        "Daniel 2:35,44-45",
        "Isaiah 2:2-3 (mountain of the Lord's house)",
        "New Testament ecclesiology of kingdom/church continuity"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Christ's second coming / future millennial kingdom that catastrophically overthrows earthly powers",
      "basis": [
        "Daniel 2:34-35,44-45 read in futurist/dispensational eschatology"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "The gospel message or spiritual power of God working without human agency",
      "basis": [
        "Daniel 2:34-35 interpreted allegorically or spiritually"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Mainstream Christian interpretation of Daniel 2 consistently treats the 'stone cut without hands' as a divine, non-human kingdom inaugurated by the Messiah; variations mainly concern whether the primary referent is Christ personally, the kingdom/Church as a whole, or the timing (already/not-yet vs. strictly future)."
}
